import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, userEvent, waitFor, within } from 'storybook/test';
import threadMeta from './thread-view.stories.tsx';
import { storyThread } from '../feed/thread-fixtures.ts';
import { authorMessages } from '../feed/author-messages.ts';

// Private reviewer evidence: exercise the real Thread parent and production caller.
// The existing parent fixture signs in Daniel; only the opener's author is changed.
// No author API or command transport is replaced, and no command is sent here.
const ThreadPage = threadMeta.component;
const actor = 'https://rezics.com/id/00000802-bbbb-7a6f-8c2d-3e7b5c1a9f40';
const ownThread = { ...storyThread, items: storyThread.items.map(item => item.reply === storyThread.focus
  ? { ...item, author: { id: actor, name: 'Daniel Chen 陈丹尼', handle: 'daniel_chen' } } : item) };
const title = 'October read-along: Pride and Prejudice, chapters 1–12';
const t = authorMessages.en;
const meta = {
  title: 'Realm/Thread opening author review', component: ThreadPage,
  args: { read: ownThread, mode: 'open', signedIn: true, locale: 'en' },
  parameters: threadMeta.parameters,
  globals: { viewport: { value: 'desktop' }, locale: 'en', theme: 'light' },
  beforeEach() { localStorage.clear(); },
  render: args => <ThreadPage {...args} />,
} satisfies Meta<typeof ThreadPage>;
export default meta;
type Story = StoryObj<typeof meta>;

async function ownOpeningMenu(canvasElement: HTMLElement) {
  const canvas = within(canvasElement);
  const opener = within(canvas.getByRole('article', { name: title }));
  const trigger = opener.getByRole('button', { name: t.menu });
  await expect(trigger).toBeVisible();
  await expect(opener.getByRole('link', { name: '11 comments' })).toHaveAttribute('href', '#comments');
  await userEvent.click(trigger);
  const body = within(canvasElement.ownerDocument.body);
  const menu = within(await body.findByRole('menu'));
  await expect(menu.getByRole('menuitem', { name: t.edit })).toBeVisible();
  await expect(menu.getByRole('menuitem', { name: t.placement })).toBeVisible();
  await userEvent.keyboard('{Escape}');
  await waitFor(() => expect(trigger).toHaveFocus());
  await userEvent.keyboard('{Enter}');
  await expect(await body.findByRole('menuitem', { name: t.edit })).toBeVisible();
  await expect(body.getByRole('menuitem', { name: t.placement })).toBeVisible();
}

export const OwnOpeningPost: Story = {
  async play({ canvasElement }) { await ownOpeningMenu(canvasElement); },
};
export const OwnOpeningPostPhone: Story = {
  globals: { viewport: { value: 'phone' } },
  async play({ canvasElement }) { await ownOpeningMenu(canvasElement); },
};
export const ForeignOpeningPost: Story = {
  args: { read: storyThread },
  async play({ canvasElement }) {
    const canvas = within(canvasElement);
    const opener = within(canvas.getByRole('article', { name: title }));
    await expect(opener.queryByRole('button', { name: t.menu })).toBeNull();
    // Own nested replies still expose their own actions, so they cannot satisfy the opener check.
    await expect(canvas.getAllByRole('button', { name: t.menu }).length).toBeGreaterThan(0);
  },
};
export const BlockedOpeningPost: Story = {
  args: { read: { ...ownThread, items: ownThread.items.map(item => item.reply === ownThread.focus
    ? { ...item, blocked: true } : item) } },
  async play({ canvasElement }) {
    const opener = within(within(canvasElement).getByRole('article', { name: 'Blocked user' }));
    await expect(opener.queryByRole('button', { name: t.menu })).toBeNull();
    await expect(opener.queryByRole('button', { name: /^Upvote/ })).toBeNull();
  },
};
export const SignedOutOpeningPost: Story = {
  args: { signedIn: false, mode: 'sign-in' },
  async play({ canvasElement }) {
    const opener = within(within(canvasElement).getByRole('article', { name: title }));
    await expect(opener.queryByRole('button', { name: t.menu })).toBeNull();
  },
};
